import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
import {escape as e} from './store.js';
import {copyCatalog} from './copy-catalog.js';
import {setSiteCopy,siteCopyValues,applyStaticCopy} from './site-copy.js';
import {appearanceColors,appearanceDefaults,normalizeAppearance,applyAppearance} from './site-appearance.js';
let appearance={...appearanceDefaults},issue='',copyDraft=null,search='',group='',tab='copy',page=0,flight,revision=0;
export async function loadSiteEditor(){if(!flight)flight=(async()=>{const stamp=revision;try{const data=await backend.publicSiteEditor();if(stamp===revision){setSiteCopy(data.copy);appearance=normalizeAppearance(data.appearance);applyAppearance(appearance);applyStaticCopy();}issue='';return true;}catch(err){issue=err.message;return false;}finally{flight=null;}})();return flight;}
export function resetSiteEditor(){copyDraft=null;search='';group='';}
export function siteEditorScreen(){if(issue)return `<section class="card"><h2>${copyHTML("site-editor.1e5f449dec0c")}</h2><p role="alert">${e(issue)}</p><button class="btn" id="site-editor-reload">${copyHTML("site-editor.7b9e42ee5b80")}</button></section>`;copyDraft??=siteCopyValues();return `<section class="card"><div class="card-head"><h2>${copyHTML("site-editor.1e5f449dec0c")}</h2><a class="btn" href="?safeAppearance=1#admin">${copyHTML("site-editor.f9b325a1d326")}</a></div><div class="actions"><button class="btn ${tab==='copy'?'primary':''}" data-site-editor-tab="copy">${copyHTML("site-editor.146382ffc03d")}</button><button class="btn ${tab==='appearance'?'primary':''}" data-site-editor-tab="appearance">${copyHTML("site-editor.02ad8411d93a")}</button></div><p class="muted">${copyHTML("site-editor.6c9c5cc1e9b4")}</p>${tab==='copy'?copyEditor():appearanceEditor()}</section>`;}
function copyEditor(){const groups=[...new Set(Object.values(copyCatalog).map(x=>x.group))].sort();const matches=Object.entries(copyCatalog).filter(([key,item])=>(!group||item.group===group)&&(!search||`${item.text} ${copyDraft[key]||''} ${item.group}`.toLowerCase().includes(search.toLowerCase())));page=Math.min(page,Math.max(0,Math.ceil(matches.length/40)-1));const entries=matches.slice(page*40,page*40+40);return `<div class="toolbar"><input id="site-copy-search" placeholder="${copyHTML("site-editor.bec9529847c8")}" aria-label="${copyHTML("site-editor.1b71fb08fdd9")}" value="${e(search)}"><select id="site-copy-group" aria-label="${copyHTML("site-editor.6302bd47623c")}"><option value="">${copyHTML("site-editor.ed5a7ff7d067")}</option>${groups.map(value=>`<option ${group===value?'selected':''}>${e(value)}</option>`).join('')}</select><button class="btn" id="site-copy-filter">${copyHTML("site-editor.638e249f4a15")}</button></div><p>${entries.length} ${copyHTML("site-editor.28391d3bc64e")} ${Object.keys(copyCatalog).length} ${copyHTML("site-editor.69cd9e9b1ac5")}</p><div class="actions"><button class="btn" id="copy-page-prev" ${page===0?'disabled':''}>Previous page</button><span>Page ${page+1} / ${Math.max(1,Math.ceil(matches.length/40))} · ${matches.length} matches</span><button class="btn" id="copy-page-next" ${(page+1)*40>=matches.length?'disabled':''}>Next page</button></div><form id="site-copy-form">${entries.map(([key,item])=>`<div class="card" style="margin:12px 0;padding:16px"><label for="copy-${key}"><small>${e(item.group)}</small><br>${e(item.text)}</label><textarea id="copy-${key}" data-copy-edit="${key}" rows="2" maxlength="5000">${e(Object.hasOwn(copyDraft,key)?copyDraft[key]:item.text)}</textarea><button type="button" class="text-button" data-copy-reset="${key}">${copyHTML("site-editor.7b591d09309b")}</button></div>`).join('')}<p id="site-copy-status" role="status"></p><button class="btn primary">${copyHTML("site-editor.cfb1fe4e78ed")}</button><button type="button" class="btn" id="site-copy-discard">${copyHTML("site-editor.cb30147eec19")}</button></form>`;}
const rangeInfo={radius:['Card corners',0,40],buttonRadius:['Button corners',0,40],fontSize:['Base font size',12,20],spacing:['Space between cards',8,40],contentWidth:['Maximum content width',800,2200],sidebarWidth:['Sidebar width',200,340]};
function appearanceEditor(){return `<form id="site-appearance-form"><h3>${copyHTML("site-editor.0d02fceebcc8")}</h3><div class="grid">${Object.entries(appearanceColors).map(([key,label])=>colorInput(key,label)).join('')}</div><h3>${copyHTML("site-editor.ca3eef198cf1")}</h3><div class="grid">${Object.entries(appearanceColors).map(([key,label])=>colorInput('dark'+key[0].toUpperCase()+key.slice(1),label)).join('')}</div>${['font','headings'].map(key=>`<label for="appearance-${key}">${key==='font'?'Body font':'Heading font'}</label><select id="appearance-${key}" name="${key}">${[['modern',copyRaw("site-editor.580c63a3f91d")],['system',copyRaw("site-editor.a6e7cd03e301")],['classic',copyRaw("site-editor.9906958b0bdb")],['mono',copyRaw("site-editor.64c223c2036f")]].map(([value,label])=>`<option value="${value}" ${appearance[key]===value?'selected':''}>${label}</option>`).join('')}</select>`).join('')}${Object.entries(rangeInfo).map(([key,[label,min,max]])=>`<label for="appearance-${key}">${label} ${copyHTML("site-editor.72c345282e4e")}</label><input id="appearance-${key}" name="${key}" type="number" min="${min}" max="${max}" value="${appearance[key]}">`).join('')}<label for="appearance-shadow">${copyHTML("site-editor.b94cea6de54c")}</label><select id="appearance-shadow" name="shadow">${['none','soft','raised'].map(value=>`<option ${appearance.shadow===value?'selected':''}>${value}</option>`).join('')}</select><label for="appearance-css">${copyHTML("site-editor.98c40fc0710e")}</label><textarea id="appearance-css" name="customCSS" rows="8" maxlength="16000" spellcheck="false">${e(appearance.customCSS)}</textarea><p class="muted">${copyHTML("site-editor.022a70005f90")}</p><p id="site-appearance-status" role="status"></p><div class="actions"><button type="button" class="btn" id="appearance-preview">${copyHTML("site-editor.db008d8b7aaa")}</button><button type="button" class="btn" id="appearance-revert">${copyHTML("site-editor.cde31ce8384e")}</button><button class="btn primary">${copyHTML("site-editor.0b96c17c8f8a")}</button><button type="button" class="btn" id="appearance-reset">${copyHTML("site-editor.fcdd708fbc96")}</button></div></form>`;}
function colorInput(key,label){return `<label>${label}<input type="color" name="${key}" value="${appearance[key]}"></label>`;}
export function bindSiteEditor(ui){const reload=document.querySelector('#site-editor-reload');if(reload)reload.onclick=async()=>{await loadSiteEditor();ui.render();};for(const button of document.querySelectorAll('[data-site-editor-tab]'))button.onclick=()=>{tab=button.dataset.siteEditorTab;applyAppearance(appearance);ui.render();};const capture=()=>{for(const field of document.querySelectorAll('[data-copy-edit]')){const key=field.dataset.copyEdit;if(field.value===copyCatalog[key].text)delete copyDraft[key];else copyDraft[key]=field.value;}};
 const copyForm=document.querySelector('#site-copy-form');if(copyForm){document.querySelector('#copy-page-prev').onclick=()=>{capture();page=Math.max(0,page-1);ui.render();};document.querySelector('#copy-page-next').onclick=()=>{capture();page++;ui.render();};copyForm.oninput=capture;document.querySelector('#site-copy-filter').onclick=()=>{capture();search=document.querySelector('#site-copy-search').value;group=document.querySelector('#site-copy-group').value;page=0;ui.render();};for(const button of copyForm.querySelectorAll('[data-copy-reset]'))button.onclick=()=>{const key=button.dataset.copyReset;delete copyDraft[key];document.getElementById('copy-'+key).value=copyCatalog[key].text;};document.querySelector('#site-copy-discard').onclick=()=>{copyDraft=null;ui.render();};copyForm.onsubmit=async event=>{event.preventDefault();capture();const status=document.querySelector('#site-copy-status'),button=copyForm.querySelector('button:not([type])');button.disabled=true;try{if(Object.values(copyDraft).some(text=>text.length>5000||/[<>\x00-\x08]/.test(text)))throw new Error(copyRaw("site-editor.36071a5b4cac"));const result=await backend.saveSiteEditor({copy:copyDraft,appearance});revision++;setSiteCopy(result.copy);copyDraft=siteCopyValues();ui.render();applyStaticCopy();ui.toast(copyRaw("site-editor.c5cfc85fcd2b"));}catch(err){status.textContent=err.message;button.disabled=false;}};}
 const form=document.querySelector('#site-appearance-form');if(form){const read=()=>normalizeAppearance(Object.fromEntries(new FormData(form)),true),status=document.querySelector('#site-appearance-status');document.querySelector('#appearance-preview').onclick=()=>{try{applyAppearance(read());status.textContent=copyRaw("site-editor.5256ebe1749e");}catch(err){status.textContent=err.message;}};document.querySelector('#appearance-revert').onclick=()=>applyAppearance(appearance);document.querySelector('#appearance-reset').onclick=()=>{for(const [key,value] of Object.entries(appearanceDefaults)){const input=form.elements.namedItem(key);if(input)input.value=value;}applyAppearance(appearanceDefaults);status.textContent=copyRaw("site-editor.be46a6c8ab39");};form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button:not([type])');button.disabled=true;try{const draft=read();const result=await backend.saveSiteEditor({copy:siteCopyValues(),appearance:draft});revision++;appearance=normalizeAppearance(result.appearance);applyAppearance(appearance);status.textContent=copyRaw("site-editor.7bce3cbf97cf");ui.toast(copyRaw("site-editor.a5d0e9867cb6"));}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};}
}
